CONCAT(COALESCE(CAST(CAST(`id` AS SIGNED) AS CHAR), '<NULL>'), '|~|', COALESCE(RTRIM(`code`), '<NULL>'), '|~|', COALESCE(RTRIM(`name`), '<NULL>'), '|~|', COALESCE(CAST(CAST(`amount` AS DECIMAL(38,6)) AS CHAR), '<NULL>'), '|~|', COALESCE(CAST(CAST(`ratio` AS DECIMAL(38,6)) AS CHAR), '<NULL>'), '|~|', COALESCE(CAST(CAST(`units` AS SIGNED) AS CHAR), '<NULL>'), '|~|', COALESCE(CASE WHEN `is_active` IS NULL THEN NULL WHEN `is_active` = 0 THEN '0' ELSE '1' END, '<NULL>'), '|~|', COALESCE(DATE_FORMAT(`born_on`, '%Y-%m-%d'), '<NULL>'), '|~|', COALESCE(DATE_FORMAT(`updated_at`, '%Y-%m-%d %H:%i:%s.%f'), '<NULL>'))
